public int lengthOfLongestSubstring(String s) {
    int[] lastSeen = new int[128];
    Arrays.fill(lastSeen, -1);
    int start = 0;
    int max = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (lastSeen[c] >= start) {
            start = lastSeen[c] + 1;
        }
        lastSeen[c] = i;
        max = Math.max(max, i - start + 1);
    }
    return max;
}

